// Общие шаги для страницы Map (Leads Map) и ссылок Google Maps (#dc2f0de9, #6e6f101d). Только просмотр, ничего не сохраняют.
// Сессия и язык — из address-helpers.ts (ADMIN_STATE, setEnglish).
import { expect, Locator, Page } from '@playwright/test';

/** Лид «test» (компания «test»): телефон и адрес из Google Places. */
export const TEST_LEAD = { name: 'test', phone: '+972531231234', address: 'Miami Beach, FL, USA' };
/** Лид «QA-map lead» без адреса (создан QA 2026-10-14). */
export const QA_MAP_LEAD = { name: 'QA-map lead', phone: '+13055550199' };

/** Начало ссылки навигации Google Maps (тикет #6e6f101d, комментарий программиста). */
export const GMAPS_DIR = 'https://www.google.com/maps/dir/?api=1&destination=';

/**
 * Перехват window.open (сохраняет адреса в window.__opened) и блок перехода на google.com/maps,
 * чтобы тест не уходил с сайта. Вызывать до page.goto.
 */
export async function trapExternalMaps(page: Page) {
  await page.addInitScript(() => {
    (window as unknown as { __opened: string[] }).__opened = [];
    window.open = ((url?: string | URL) => {
      (window as unknown as { __opened: string[] }).__opened.push(String(url ?? ''));
      return null;
    }) as typeof window.open;
  });
  await page.route(/^https:\/\/(www\.)?google\.com\/maps\/dir/, (route) => route.abort());
}

export async function openedUrls(page: Page): Promise<string[]> {
  return page.evaluate(() => (window as unknown as { __opened: string[] }).__opened ?? []);
}

/** Страница Map: дождаться списка лидов. */
export async function openLeadsMap(page: Page) {
  await page.goto('/map');
  await expect(page.getByText(/^Leads List \(\d+\)$/)).toBeVisible();
}

/** Карточка лида в «Leads List»: самый вложенный блок с заголовком-именем и телефоном. */
export function leadCard(page: Page, name: string, phone: string): Locator {
  return page
    .locator('main div')
    .filter({ has: page.getByRole('heading', { name, exact: true }) })
    .filter({ hasText: phone })
    .last();
}

/** Строки текста карточки (без пустых). */
export async function cardLines(card: Locator, mustContain: string): Promise<string[]> {
  await expect(card).toContainText(mustContain);
  return (await card.innerText()).split('\n').map((l) => l.trim()).filter(Boolean);
}

/** /leads: открыть «Lead Details» лида по телефону (кнопка с иконкой file-text, без подписи). */
export async function openLeadDetails(page: Page, phone: string): Promise<Locator> {
  await page.goto('/leads');
  await expect(page.locator('main')).toContainText(phone);
  const detailsBtn = page.locator('button:visible').filter({ has: page.locator('svg.lucide-file-text') });
  const entry = page.locator('tr:visible, div:visible').filter({ hasText: phone }).filter({ has: detailsBtn }).last();
  await entry.locator('button:visible').filter({ has: page.locator('svg.lucide-file-text') }).first().click();
  const dialog = page.getByRole('dialog').last();
  await expect(dialog).toContainText('Lead Details');
  return dialog;
}

/** /jobs → вкладка статуса → превью работы (кнопка title="Preview"). */
export async function openJobPreview(page: Page, statusTab: string, jobId: string): Promise<Locator> {
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText('JOB-00');
  await page.getByRole('tab', { name: statusTab, exact: true }).click();
  const row = page.locator('tr', { hasText: jobId }).first();
  await expect(row).toBeVisible();
  await row.getByTitle('Preview').click();
  const dialog = page.getByRole('dialog').last();
  await expect(dialog).toContainText(jobId);
  return dialog;
}

/** Ссылки навигации Google Maps внутри области. */
export const gmapsDirLinks = (area: Locator) => area.locator(`a[href^="${GMAPS_DIR}"]`);
